diff --git a/lib/utils/parse/ast.go b/lib/utils/parse/ast.go
new file mode 100644
index 0000000..33b1a2b
--- /dev/null
+++ b/lib/utils/parse/ast.go
@@ -0,0 +1,166 @@
+package parse
+
+import (
+	"net/mail"
+	"reflect"
+	"regexp"
+	"strconv"
+	"strings"
+
+	"github.com/gravitational/trace"
+)
+
+// Expr is a typed expression that can be evaluated with a context.
+type Expr interface {
+	String() string
+	Kind() reflect.Kind
+	Evaluate(EvaluateContext) (any, error)
+}
+type EvaluateContext struct {
+	VarValue     func(VarExpr) ([]string, error)
+	MatcherInput string
+}
+type StringLitExpr struct{ Value string }
+
+func (e StringLitExpr) String() string                        { return strconv.Quote(e.Value) }
+func (StringLitExpr) Kind() reflect.Kind                      { return reflect.String }
+func (e StringLitExpr) Evaluate(EvaluateContext) (any, error) { return []string{e.Value}, nil }
+
+type VarExpr struct{ Namespace, Name string }
+
+func (e VarExpr) String() string   { return e.Namespace + "." + e.Name }
+func (VarExpr) Kind() reflect.Kind { return reflect.String }
+func (e VarExpr) Evaluate(c EvaluateContext) (any, error) {
+	if c.VarValue == nil {
+		return nil, trace.BadParameter("variable resolver is missing for %s", e.String())
+	}
+	return c.VarValue(e)
+}
+
+type EmailLocalExpr struct{ Input Expr }
+
+func (e EmailLocalExpr) String() string   { return "email.local(" + e.Input.String() + ")" }
+func (EmailLocalExpr) Kind() reflect.Kind { return reflect.String }
+func (e EmailLocalExpr) Evaluate(c EvaluateContext) (any, error) {
+	vals, err := stringValues(e.Input, c)
+	if err != nil {
+		return nil, err
+	}
+	out := make([]string, 0, len(vals))
+	for _, v := range vals {
+		if v == "" {
+			return nil, trace.BadParameter("email address is empty")
+		}
+		a, err := mail.ParseAddress(v)
+		if err != nil {
+			return nil, trace.BadParameter("invalid email address %q: %v", v, err)
+		}
+		parts := strings.SplitN(a.Address, "@", 2)
+		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
+			return nil, trace.BadParameter("missing local part in email address %q", v)
+		}
+		out = append(out, parts[0])
+	}
+	return out, nil
+}
+
+type RegexpReplaceExpr struct {
+	Input                Expr
+	Pattern, Replacement string
+	re                   *regexp.Regexp
+}
+
+func (e RegexpReplaceExpr) String() string {
+	return "regexp.replace(" + e.Input.String() + ", " + strconv.Quote(e.Pattern) + ", " + strconv.Quote(e.Replacement) + ")"
+}
+func (RegexpReplaceExpr) Kind() reflect.Kind { return reflect.String }
+func (e RegexpReplaceExpr) Evaluate(c EvaluateContext) (any, error) {
+	vals, err := stringValues(e.Input, c)
+	if err != nil {
+		return nil, err
+	}
+	re := e.re
+	if re == nil {
+		re, err = compileRegexp(e.Pattern)
+		if err != nil {
+			return nil, err
+		}
+	}
+	out := make([]string, 0, len(vals))
+	for _, v := range vals {
+		if re.MatchString(v) {
+			out = append(out, re.ReplaceAllString(v, e.Replacement))
+		}
+	}
+	return out, nil
+}
+
+type RegexpMatchExpr struct {
+	Pattern string
+	re      *regexp.Regexp
+}
+
+func (e RegexpMatchExpr) String() string   { return "regexp.match(" + strconv.Quote(e.Pattern) + ")" }
+func (RegexpMatchExpr) Kind() reflect.Kind { return reflect.Bool }
+func (e RegexpMatchExpr) Evaluate(c EvaluateContext) (any, error) {
+	re := e.re
+	if re == nil {
+		var err error
+		re, err = compileRegexp(e.Pattern)
+		if err != nil {
+			return nil, err
+		}
+	}
+	return re.MatchString(c.MatcherInput), nil
+}
+
+type RegexpNotMatchExpr struct {
+	Pattern string
+	re      *regexp.Regexp
+}
+
+func (e RegexpNotMatchExpr) String() string {
+	return "regexp.not_match(" + strconv.Quote(e.Pattern) + ")"
+}
+func (RegexpNotMatchExpr) Kind() reflect.Kind { return reflect.Bool }
+func (e RegexpNotMatchExpr) Evaluate(c EvaluateContext) (any, error) {
+	v, err := RegexpMatchExpr{Pattern: e.Pattern, re: e.re}.Evaluate(c)
+	if err != nil {
+		return nil, err
+	}
+	return !v.(bool), nil
+}
+func stringValues(e Expr, c EvaluateContext) ([]string, error) {
+	if e.Kind() != reflect.String {
+		return nil, trace.BadParameter("string expression required, got %s", e.String())
+	}
+	v, err := e.Evaluate(c)
+	if err != nil {
+		return nil, err
+	}
+	out, ok := v.([]string)
+	if !ok {
+		return nil, trace.BadParameter("expression %s did not evaluate to strings", e.String())
+	}
+	return out, nil
+}
+func compileRegexp(pattern string) (*regexp.Regexp, error) {
+	re, err := regexp.Compile(pattern)
+	if err != nil {
+		return nil, trace.BadParameter("invalid regexp %q: %v", pattern, err)
+	}
+	return re, nil
+}
+func validateExpr(e Expr) error {
+	switch v := e.(type) {
+	case VarExpr:
+		if v.Name == "" {
+			return trace.BadParameter("variable %q must have exactly two components: namespace.name", v.String())
+		}
+	case EmailLocalExpr:
+		return validateExpr(v.Input)
+	case RegexpReplaceExpr:
+		return validateExpr(v.Input)
+	}
+	return nil
+}
